  uiStatus.style.opacity = "1";
  if (stageTimer) { clearTimeout(stageTimer); stageTimer = null; }
  if (stageSlowTimer) { clearTimeout(stageSlowTimer); stageSlowTimer = null; }
  if (!label) return;

  if (ms > 0) {
    stageTimer = setTimeout(() => {
      if (uiStatus.textContent === label) uiStatus.textContent = "";
    }, ms);
    return;
  }

